{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0012",
          "reason": "State foreign-policy statement on the Korean Peninsula, not a Trọng-specific 2022 nuclear or command-and-control choice."
        },
        {
          "evidence_id": "E0013",
          "reason": "Global NPT conference context, not evidence of Vietnamese or Trọng-specific conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct 2022 Trọng-level nuclear, command-and-control, or crisis-de-escalation decision is evidenced.",
          "lenses": ["1B.3", "1B.8"],
          "best_source_or_query_direction": "CPV/CMC or foreign-policy records that would show a ruler-attributed 2022 nuclear or existential-risk decision.",
          "why_it_matters": "Without a target-period choice, the chapter remains a null-style exposure case and should not be read as personal merit or blame."
        }
      ],
      "reason": "Fair as a limited-exposure case: the package distinguishes Vietnam's treaty posture and peaceful-use diplomacy from Trọng's lack of direct 2022 nuclear authority."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0022",
          "reason": "External ambassadors' op-ed and pressure context, not conduct by Trọng or an independent finding about Vietnam's actions."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct ruler-level initiation, escalation, proxy control, or peace-management authority is thin.",
          "lenses": ["2B.5", "2B.9"],
          "best_source_or_query_direction": "Top-level party, foreign-ministry, or defense-council records tied to Ukraine, China, and other 2022 security choices.",
          "why_it_matters": "The package fairly shows restraint and diplomacy, but only modestly ties those outcomes to Trọng personally."
        }
      ],
      "reason": "Fairly presents cautious state diplomacy and the limits of personal attribution; it does not overstate war-making or peacemaking."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "Fairly presents a repressive domestic pattern plus some corrective and protective counterevidence, while keeping attribution mostly at the state-system level."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "Strong and fair presentation of formal control architecture, 2022 enforcement, and the limited rights-protective language that sits beside it."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Direct ruler-attributed economic appointment and household-level distribution evidence is thinner than the macro and program evidence.",
          "lenses": ["5B.2", "5B.8"],
          "best_source_or_query_direction": "Personnel records, provincial implementation audits, and household or wage microdata for 2022.",
          "why_it_matters": "Prevents macro outcomes from being over-ascribed to Trọng when execution was shared across ministries, SBV, and local authorities."
        }
      ],
      "reason": "Fairly presents mixed economic stewardship, including programs, implementation bottlenecks, and favorable macro outcomes, while not pretending the attribution is cleaner than it is."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Direct personal role in service delivery is mostly indirect, and adult coverage or subgroup outcome detail remains incomplete.",
          "lenses": ["6B.2", "6B.3", "6B.10"],
          "best_source_or_query_direction": "Program evaluations, ministry reports, and subgroup-disaggregated surveys for 2022 social-service delivery.",
          "why_it_matters": "The package can show welfare-oriented action and structural gaps, but not a clean ruler-level causal chain for every service domain."
        }
      ],
      "reason": "Fairly presents both the welfare-oriented actions and the remaining structural deficits, with baseline and attribution caveats intact."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0046",
          "reason": "Succession and closed-party nomination context from 2021, not evidence of personal honesty or dishonesty in 2022."
        },
        {
          "evidence_id": "E0087",
          "reason": "Self-defensive media snippet; useful as context, but not independent evidence of personal integrity."
        },
        {
          "evidence_id": "E0088",
          "reason": "Enforcement against other officials; does not show Trọng's own assets, family interests, or concealed benefit."
        },
        {
          "evidence_id": "E0089",
          "reason": "Interpretive analysis of campaign politics, not a direct finding of deception, self-dealing, or hidden conflicts."
        }
      ],
      "material_gaps": [
        {
          "gap": "No verified direct evidence on Trọng's own assets, family/business links, gifts, or independent findings about his personal conflicts of interest.",
          "lenses": ["7B.3", "7B.4", "7B.6"],
          "best_source_or_query_direction": "Asset declarations, investigative records, sanctions findings, or court/audit material naming him directly.",
          "why_it_matters": "The current file mostly proves anti-corruption posture and campaign effects, not a defensible judgment about Trọng's personal integrity."
        }
      ],
      "reason": "Not fully fair yet: the package still lacks direct personal-nexus evidence and relies too heavily on anti-corruption posture, campaign effects, and self-presentation rather than independent evidence about Trọng himself."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Personnel replacement and subnational implementation chain are not cleanly audited, so some progress is still inferred from system-level records.",
          "lenses": ["8B.4", "8B.5", "8B.8"],
          "best_source_or_query_direction": "Cadre rotation records, ministry staffing changes, and district-level implementation audits for 2022.",
          "why_it_matters": "It limits how confidently the program-to-results chain can be tied to Trọng rather than the broader party-state apparatus."
        }
      ],
      "reason": "Fairly presents the program-to-implementation chain, including direct steering, bottlenecks, and outcome data, while keeping the distinction between Trọng's role and system execution visible."
    }
  ]
}
